import useSWR from "swr";
import { Item } from "@/types/item";

type ItemListResponse = {
  data: Item[];
};

export const useItemListSWR = () => {
  const { data, error, isLoading } = useSWR<ItemListResponse>("/api/items");

  return {
    items: data?.data ?? [],
    isLoading,
    error,
  };
};
